import 'dart:convert';import 'dart:io';import 'dart:math';import 'remote_session.dart';import 'universe_ir.dart';
class SyntheticJobSnapshot{const SyntheticJobSnapshot({required this.id,required this.state,required this.cursor,required this.totalUnits,required this.searchSpaceSha256,required this.toyEnumerationSha256,required this.resultSha256});final String id,state,searchSpaceSha256,toyEnumerationSha256;final int cursor,totalUnits;final String? resultSha256;bool get completed=>state=='COMPLETED';}
abstract interface class SyntheticJobGateway{Future<SyntheticJobSnapshot> create(String origin,String access,UniverseSessionDraft draft,String idem);Future<SyntheticJobSnapshot> get(String origin,String access,String jobId);}
class HttpsSyntheticJobGateway implements SyntheticJobGateway{const HttpsSyntheticJobGateway();Uri _origin(String v){final u=Uri.tryParse(v.trim());if(u==null||u.scheme!='https'||u.host.isEmpty||u.userInfo.isNotEmpty||(u.path.isNotEmpty&&u.path!='/')||u.query.isNotEmpty||u.fragment.isNotEmpty)throw const FormatException('HTTPS_ORIGIN_REQUIRED');return u;}Future<Map<String,dynamic>> _request(Uri u,String t,{Map<String,Object?>? body})async{final c=HttpClient()..connectionTimeout=const Duration(seconds:8);try{final q=body==null?await c.getUrl(u).timeout(const Duration(seconds:8)):await c.postUrl(u).timeout(const Duration(seconds:8));q.followRedirects=false;q.headers.set(HttpHeaders.authorizationHeader,'Bearer $t');if(body!=null){q.headers.contentType=ContentType.json;q.write(jsonEncode(body));}final r=await q.close().timeout(const Duration(seconds:8)),bytes=<int>[];await for(final x in r.timeout(const Duration(seconds:8))){bytes.addAll(x);if(bytes.length>65536)throw const FormatException('JOB_RESPONSE_TOO_LARGE');}if(r.statusCode!=200&&r.statusCode!=202)throw FormatException('JOB_HTTP_${r.statusCode}');final d=jsonDecode(utf8.decode(bytes,allowMalformed:false));if(d is! Map<String,dynamic>)throw const FormatException('JOB_NOT_OBJECT');return d;}finally{c.close(force:true);}}SyntheticJobSnapshot _parse(Map<String,dynamic>d){const k={'schema','mode','scientific_authority','job_id','state','cursor','total_units','search_space_sha256','toy_enumeration_sha256','result_sha256','economic_backtests','holdout_open','ga2_open','mt5_executed'};if(d.keys.toSet().difference(k).isNotEmpty||k.difference(d.keys.toSet()).isNotEmpty||d['schema']!='QROS_G12_SYNTHETIC_JOB_V1'||d['mode']!='TEST_ONLY_SYNTHETIC'||d['scientific_authority']!='NONE'||d['economic_backtests']!=0||d['holdout_open']!=false||d['ga2_open']!=false||d['mt5_executed']!=false||d['job_id'] is! String||d['state'] is! String||d['cursor'] is! int||d['total_units'] is! int||d['search_space_sha256'] is! String||d['toy_enumeration_sha256'] is! String||(d['result_sha256']!=null&&d['result_sha256'] is! String))throw const FormatException('JOB_SCHEMA_INVALID');return SyntheticJobSnapshot(id:d['job_id'] as String,state:d['state'] as String,cursor:d['cursor'] as int,totalUnits:d['total_units'] as int,searchSpaceSha256:d['search_space_sha256'] as String,toyEnumerationSha256:d['toy_enumeration_sha256'] as String,resultSha256:d['result_sha256'] as String?);}@override Future<SyntheticJobSnapshot> create(String o,String a,UniverseSessionDraft d,String i)async{final u=_origin(o),n=d.blueprint.rawBirths;if(n<1||n>10000)throw const FormatException('JOB_BUDGET_INVALID');return _parse(await _request(u.replace(path:'/v1/jobs'),a,body:{'search_space_sha256':d.searchSpaceSha256,'toy_enumeration_sha256':d.toyEnumerationSha256,'total_units':n,'idempotency_key':i}));}@override Future<SyntheticJobSnapshot> get(String o,String a,String id)async{if(!RegExp(r'^job_[A-Za-z0-9_-]{20,80}$').hasMatch(id))throw const FormatException('JOB_ID_INVALID');return _parse(await _request(_origin(o).replace(path:'/v1/jobs/$id'),a));}}
String newIdempotencyKey(){final r=Random.secure(),b=List<int>.generate(18,(_)=>r.nextInt(256));return base64UrlEncode(b).replaceAll('=','');}
